{"kind":"tool","id":"gYVV8C9dPzU","toolName":"write_file","input":{"path":"tests/db/debug2.test.ts","content":"// @vitest-environment node
import { beforeAll, expect, it } from "vitest";
import type { PGlite } from "@electric-sql/pglite";

import { asUser, createTestDatabase, createUser } from "./harness";

let db: PGlite;
let devId: string;

beforeAll(async () => {
  db = await createTestDatabase();
  devId = await createUser(db, "repro@example.test");
}, 120_000);

it("isolates RETURNING + RLS", async () => {
  // 1. Trivial policy: WITH CHECK (true)
  await db.exec(`
    create table public.repro1 (id uuid primary key default gen_random_uuid(), name text);
    alter table public.repro1 enable row level security;
    grant all on public.repro1 to authenticated;
    create policy repro1_all on public.repro1 for insert to authenticated with check (true);
    create policy repro1_sel on public.repro1 for select to authenticated using (true);
  `);

  // 2. Policy calling a security-definer function (like our forms policy)
  await db.exec(`
    create table public.repro2 (id uuid primary key default gen_random_uuid(), name text);
    alter table public.repro2 enable row level security;
    grant all on public.repro2 to authenticated;
    create policy repro2_ins on public.repro2 for insert to authenticated
      with check (app_private.has_role('developer'));
    create policy repro2_sel on public.repro2 for select to authenticated using (true);
  `);

  const results: Record<string, string> = {};

  for (const [label, sql] of [
    ["repro1 no-returning", `insert into public.repro1 (name) values ('a')`],
    ["repro1 returning", `insert into public.repro1 (name) values ('a') returning id`],
    ["repro2 no-returning", `insert into public.repro2 (name) values ('b')`],
    ["repro2 returning", `insert into public.repro2 (name) values ('b') returning id`],
    ["repro1 returning via cte",
      `with ins as (insert into public.repro1 (name) values ('c') returning id) select count(*) from ins`],
  ] as const) {
    try {
      await asUser(db, devId, async () => {
        await db.query(sql);
      });
      results[label] = "ok";
    } catch (error) {
      results[label] = (error as Error).message;
    }
  }

  console.log(JSON.stringify(results, null, 2));
  expect(results).toBeDefined();
  await db.close();
});
"}}


